package com.curso.services;
import com.curso.cotacao.BrapiCatalogoClient;import com.curso.domains.dtos.InvestimentoDTOs.*;import com.curso.services.exceptions.CatalogoIndisponivelException;import java.time.*;import java.util.*;import java.util.regex.Pattern;import org.springframework.stereotype.Service;
@Service public class CatalogoAtivosService{private static final Duration VALIDADE=Duration.ofHours(6),REPETIR_APOS=Duration.ofMinutes(1);private static final Pattern SIMBOLO=Pattern.compile("[A-Z0-9][A-Z0-9.-]{0,19}");private final BrapiCatalogoClient client;private final Clock clock;private volatile Cache cache;private volatile Instant repetirEm=Instant.MIN;public CatalogoAtivosService(BrapiCatalogoClient c,Clock clock){client=c;this.clock=clock;}
 public PaginaAtivosResponse listar(String busca,int pagina,int tamanho){String filtro=busca==null?"":busca.trim().toUpperCase(Locale.ROOT);if(!filtro.matches("[A-Z0-9.-]{0,20}")||pagina<0||tamanho<1||tamanho>100)throw new IllegalArgumentException("Parâmetros de busca ou paginação inválidos");Resultado atual=obter();List<String> filtrados=atual.cache().simbolos().stream().filter(s->s.contains(filtro)).toList();long inicio=(long)pagina*tamanho;List<AtivoCatalogoResponse> itens=inicio>=filtrados.size()?List.of():filtrados.subList((int)inicio,(int)Math.min(filtrados.size(),inicio+tamanho)).stream().map(AtivoCatalogoResponse::new).toList();return new PaginaAtivosResponse(itens,pagina,tamanho,filtrados.size(),atual.cache().atualizadoEm(),atual.desatualizado());}
 private Resultado obter(){Instant agora=clock.instant();Cache l=cache;if(l!=null&&agora.isBefore(l.atualizadoEm().plus(VALIDADE)))return new Resultado(l,false);synchronized(this){agora=clock.instant();l=cache;if(l!=null&&agora.isBefore(l.atualizadoEm().plus(VALIDADE)))return new Resultado(l,false);if(agora.isBefore(repetirEm)){if(l!=null)return new Resultado(l,true);throw new CatalogoIndisponivelException();}try{List<String> simbolos=client.buscar().stream().filter(Objects::nonNull).map(s->s.trim().toUpperCase(Locale.ROOT)).filter(s->SIMBOLO.matcher(s).matches()).distinct().sorted().toList();Cache novo=new Cache(simbolos,agora);cache=novo;repetirEm=Instant.MIN;return new Resultado(novo,false);}catch(RuntimeException e){repetirEm=agora.plus(REPETIR_APOS);if(l!=null)return new Resultado(l,true);throw new CatalogoIndisponivelException(e);}}}
 private record Cache(List<String> simbolos,Instant atualizadoEm){}private record Resultado(Cache cache,boolean desatualizado){}
}
